3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Validates a new owner before {@link BuildOwner} runs: every one of firstName, lastName, address,
13	 * city and telephone must be present and non-blank. Any that are missing or blank are collected and
14	 * reported together as a {@link MissingOwnerFieldsException} (a 400), so the body is never persisted.
15	 *
16	 * <p>Deliberately does <em>not</em> use {@code @Valid}: bean validation would raise a
17	 * {@code MethodArgumentNotValidException} with a different response shape, whereas this rule must
18	 * answer with an {@code errors} array naming each offending field.
19	 */
20	public class ValidateNewOwner {
21	
22	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
23	            throws MissingOwnerFieldsException {
24	        // This list mirrors OwnerFieldsDto's required fields by hand: it must track the schema's
25	        // `required` set. We check presence/non-blankness only, a narrower rule than the DTO's full
26	        // constraints (@Size/@Pattern), so bean validation is intentionally not used here.
27	        List<String> missing = new ArrayList<>();
28	        require(missing, "firstName", request.getFirstName());
29	        require(missing, "lastName", request.getLastName());
30	        require(missing, "address", request.getAddress());
31	        require(missing, "city", request.getCity());
32	        require(missing, "telephone", request.getTelephone());
33	        if (!missing.isEmpty()) {
34	            throw new MissingOwnerFieldsException(missing);
35	        }
36	        validated.set(request);
37	    }
38	
39	    private static void require(List<String> missing, String field, String value) {
40	        if (value == null || value.isBlank()) {
41	            missing.add(field);
42	        }
43	    }
44	}
