9	/**
10	 * Responds 400 with an RFC-7807 {@link ProblemDetail} (built through the shared {@link ProblemDetails}
11	 * helper, like every other handler in this package) whose {@code errors} array lists the name of each
12	 * required owner field that was missing or blank, e.g. {@code "errors":["city","telephone"]}.
13	 */
14	public class MissingOwnerFieldsExceptionHandler {
15	
16	    public void handle(@Parameter MissingOwnerFieldsException ex,
17	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
18	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.BAD_REQUEST,
19	                "The request is missing one or more required owner fields");
20	        detail.setProperty("errors", ex.getFields());
21	        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST).body(detail));
22	    }
23	}
