5	/**
6	 * Thrown when a request to create an owner omits or blanks one or more required fields.
7	 * Carries the names of the offending fields so {@link MissingOwnerFieldsExceptionHandler}
8	 * can report them in the response's {@code errors} array. Checked so it appears in the
9	 * function's {@code throws} clause and is routed as an escalation.
10	 */
11	public class MissingOwnerFieldsException extends Exception {
12	
13	    private final List<String> fields;
14	
15	    public MissingOwnerFieldsException(List<String> fields) {
16	        super("Missing or blank required owner fields: " + fields);
17	        this.fields = List.copyOf(fields);
18	    }
19	
20	    public List<String> getFields() {
21	        return this.fields;
22	    }
23	}
